def level_of_deep(paren_string: str) -> int:
    """ Input to this function is a string representing a group of nested parentheses.
    The output is the number of maximum nesting of the parentheses. 

    >>> level_of_deep('(()())')
    2
    >>> level_of_deep('((()))')
    3
    """
    stack = []
    deepest_level = 0
    for char in paren_string:
        if char == '(':
            stack.append(char)
        elif char == ')':
            try:
                stack.pop()
            except IndexError:
                continue
            if len(stack) > deepest_level:
                deepest_level = len(stack)
    return deepest_level

